from scipy.ndimage import label
def comps(g):
 a=np.array(g); lab,n=label(a>0)
 out=[]
 for k in range(1,n+1):
  coords=np.argwhere(lab==k); vals=a[lab==k]; col=next(v for v in vals if v!=5)
  out.append((col,coords,vals))
 return out

def best_maps(pair):
 g=np.array(pair['input']); o=np.array(pair['output']); H,W=o.shape
 res=[]
 for col,coords,vals in comps(g):
  opts=[]
  for typ in range(8):
   cc=coords.copy()
   if typ>=4: cc=cc[:,::-1]
   for _ in range(typ%4): cc=np.stack([cc[:,1],-cc[:,0]],1)
   cc-=cc.min(0); h,w=cc.max(0)+1
   for dr in range(-h-2,H+2):
    for dc in range(-w-2,W+2):
     c2=cc+[dr,dc]; inside=(c2[:,0]>=0)&(c2[:,0]<H)&(c2[:,1]>=0)&(c2[:,1]<W)
     match=inside&(o[c2[:,0].clip(0,H-1),c2[:,1].clip(0,W-1)]==vals)
     opts.append((int(match.sum()),int(inside.sum()),-int((inside&~match).sum()),typ,dr,dc))
  res.append((col,sorted(opts,reverse=True)[:3]))
 return res
